M5_RETURN_IN_LOOP.question:
def first(xs):
    for x in xs:
        return x

print(first([7, 8, 9]))

def f(xs):
    t = 0
    for x in xs:
        t += x
        return t

print(f([1, 2, 3]))

def f(n):
    for i in range(n):
        if i == 2:
            return i
    return -1

print(f(5))

def has_even(xs):
    for x in xs:
        if x % 2 == 0:
            return True
        else:
            return False

print(has_even([1, 2, 4]))
